def key(L, n, m): return f"{L},{n},{m}"

# ---------- K. exactness and validation of the block method (4^4) ----------
t = time.time(); rng = np.random.default_rng(20261024); L = 4
th2 = 0.3 * rng.normal(size=L); th4 = 0.3 * rng.normal(size=L)
qb, gw = qdens_axis(th2, th4, want_gw=True)
X4 = np.indices((L,) * 4); th = np.zeros((4,) + (L,) * 4); th[1] = th2[X4[0]]; th[3] = th4[X4[2]]
w, v = np.linalg.eigh(build_H_full(th.reshape(4, -1)))
qf = np.einsum('xn,n,xn->x', v, np.sign(w), v.conj()).real.reshape(L ** 4, 4).sum(1).reshape((L,) * 4); del v
dv = np.abs(qf - qb[:, None, :, None]).max()
check("K1 4^4: block-diagonal (p2,p4) density = full dense 4D density (dim 1024); per block GW exact, sign(H)^2 = 1",
      dv < 1e-12 and gw < 1e-12, f"|q_block - q_full| {dv:.0e}, GW/proj {gw:.0e}, {time.time()-t:.1f}s")

# ---------- K2. laptop re-run of the Mac-mini pipeline ----------
t = time.time(); pos6, rd6 = M1(6, 24); d6 = np.abs(pos6 - np.array(DATA['M1']['6'])).max()
a, b = M2pair(8, 1, 1, 24); a = (a * np.exp(1j * np.pi / 4)).real; b = (b * np.exp(1j * np.pi / 4)).real
e8 = DATA['M2'][key(8, 1, 1)]; d8 = max(abs(a - e8[0]), abs(b - e8[1]))
check("K2 laptop re-run = embedded Mac-mini values: order-2 kernel on 6 x 24 x 6 x 24 and single-mode 16 / doublet "
      "coefficients on 8 x 24 x 8 x 24", d6 < 1e-10 and d8 < 1e-10, f"kernel {d6:.0e}, single-mode {d8:.0e}; {time.time()-t:.0f}s")

# ---------- F. the finite-volume artefact that forced T = 24 ----------
t = time.time(); r0 = M2pair(8, 1, 1, 8)[0]; r1 = M2pair(8, 1, 1, 8, shift=np.pi / 8)[0]
r0 = (r0 * np.exp(1j * np.pi / 4)).real; r1 = (r1 * np.exp(1j * np.pi / 4)).real
ho = DATA['hol']; tt = DATA['M2T']
check("F1 isotropic 8^4: a pure x2/x4 holonomy shift (th -> th + pi/8, field strengths unchanged) flips the 16's "
      "coefficient R16(pi/4,pi/4), so isotropic data are Polyakov-loop dominated; with T = 24 the shift moves it by "
      "< 1% and T = 16/24/32 on L = 12 agree to < 2% (T = 24 vs 32: < 0.1%)",
      r0 < 0 < r1 and abs(ho['24'][1] / ho['24'][0] - 1) < 0.01 and abs(tt['16'][0] / tt['32'][0] - 1) < 0.02
      and abs(tt['24'][0] / tt['32'][0] - 1) < 1e-3,
      f"iso {r0:+.2e} -> {r1:+.2e} (live, {time.time()-t:.0f}s); T=24 shift {ho['24'][0]:.4e} -> {ho['24'][1]:.4e}; "
      f"L=12: T16 {tt['16'][0]:.4e}, T24 {tt['24'][0]:.4e}, T32 {tt['32'][0]:.4e}")

# ---------- P1-P4: per-charge order-2 kernel (m0 = 1.6, T = 24) ----------
LS = sorted(int(k) for k in DATA['M1']); POS = {L: np.array(DATA['M1'][str(L)]) for L in LS}
KER = {L: kernel_from_pi(L, POS[L]) for L in LS}; ENV = {L: envelope(L, POS[L]) for L in LS}
XI = {L: xi_fit(ENV[L], 2, L // 2 - 1) for L in LS if L >= 10}
print("order-2 kernel, m0 = 1.6, T = 24: envelope max|Pi| at d = 1..L/2-1, fitted xi; sum_ab Q / (2/(4pi^2)) - 1:")
for L in LS:
    print(f"  L={L:2d}: " + " ".join(f"{e:.1e}" for e in ENV[L][1:L // 2]) + (f"  xi {XI[L]:.2f}" if L in XI else "")
          + f"  dS {KER[L][2].sum()/GAM-1:+.2%}")
xv = np.array(list(XI.values())); spread = (xv.max() - xv.min()) / xv.mean()
c12 = abs(KER[12][0][3, 3] - KER[16][0][4, 4]) / GAM
check("P1 pre-set NOT MET (xi part): kernel decay lengths at L = 10, 12, 16 differ by > 10% (they grow with L: a "
      "slower second scale); the common-momentum part IS met (|Q~_12 - Q~_16| at (pi/2,pi/2) < 1e-3 gamma)",
      spread > 0.10 and c12 < 1e-3, "xi " + ", ".join(f"L{L} {x:.3f}" for L, x in XI.items())
      + f" (spread {spread:.0%}); common momentum {c12:.1e} gamma")
dS = {L: KER[L][2].sum() / GAM - 1 for L in LS}
mu_fit = -np.log(dS[16] / dS[12]) / 4; ginf = KER[16][2].sum() - (KER[16][2].sum() - KER[12][2].sum()) / (1 - np.exp(mu_fit * 4))
check("P2 pre-set NOT MET: sum_ab Q is not within 1% of 2/(4 pi^2) for L >= 10; it converges exponentially "
      "(rate mu ~ 0.3/site) and the post-hoc two-point extrapolation (L = 12, 16) lands within 0.5%", all(abs(dS[L]) > 0.01 for L in (10, 12, 16)) and abs(ginf / GAM - 1) < 0.005,
      ", ".join(f"L{L} {dS[L]:+.2%}" for L in LS) + f"; mu {mu_fit:.2f}; extrapolated {ginf/GAM-1:+.2%}")
Qt, _, Q = KER[16]; grec = Q.sum(); K1, K3 = currents(16, Q, grec); e1 = envelope(16, K1); e3 = envelope(16, K3)
xK1 = xi_fit(e1, 2, 7); xK3 = xi_fit(e3, 2, 7); xK3b = xi_fit(e3, 2, 6); tail = max(e1[7:].max(), e3[7:].max()) / GAM
check("P3 pre-set PARTLY MET: on L = 16 the Luscher-split currents K1, K3 of Q - gamma delta have tails < 1e-3 gamma "
      "and xi(K1) within 15% of xi(Pi); xi(K3) on the pre-coded range d = 2..7 is not (its d = 7 point is forced ~0 "
      "by the periodic construction; d = 2..6 shown)",
      tail < 1e-3 and abs(xK1 / XI[16] - 1) < 0.15 and abs(xK3 / XI[16] - 1) > 0.15,
      f"tail {tail:.0e} gamma; xi(K1) {xK1:.2f}, xi(K3) {xK3:.2f} [d<=6: {xK3b:.2f}], xi(Pi) {XI[16]:.2f}")
plat = {}
for L in LS:
    _, K3d = currents(L, -0.25 * KER[L][2], 0.0); plat[L] = abs(K3d[0, L // 2]) / abs(GAML) - 1
check("P4 doublet: its would-be gauge-invariant current (no T term) has a NON-decaying tail |K3'(L/2)| = "
      "|gamma_L|(1 + dS); within 2% only at L = 16 (pre-set 'every L' NOT MET: the P2 offset)",
      abs(plat[16]) < 0.02 and all(abs(plat[L]) > 0.02 for L in LS if L < 16),
      ", ".join(f"L{L} {plat[L]:+.1%}" for L in LS))

# ---------- P4b-P6: single-mode finite field (eps = 0.3), m0 = 1.6, T = 24 ----------
M2 = {tuple(int(t) for t in k.split(',')): v for k, v in DATA['M2'].items()}
def sv(L, n): return np.sin(np.pi * n / L) ** 2
pts = [(sv(L, n), sv(L, m), v) for (L, n, m), v in M2.items() if L in (12, 16) and 2 * n != L and 2 * m != L]
cL, rL = symfit([p[0] for p in pts], [p[1] for p in pts], np.array([p[2][1] for p in pts]), 3)
diag = sorted((sv(L, n), L, n, v) for (L, n, m), v in M2.items() if n == m and L >= 12 and 2 * n != L)
print("diagonal p = k (m0 = 1.6): s = sin^2(p/2), L, R16, R_L/gamma_L:")
print("  " + "; ".join(f"{s:.3f} L{L} {v[0]:+.2e} {v[1]/GAML:.3f}" for s, L, n, v in diag))
lin = diag[0][3][1] / GAML - diag[0][0] * (diag[1][3][1] - diag[0][3][1]) / GAML / (diag[1][0] - diag[0][0])
check("P4b pre-set NOT MET: the pooled cubic fit of R_L(p,k) (L = 12, 16) misses gamma_L by > 3% (strong momentum "
      "dependence at m0 = 1.6); post-hoc, the two smallest diagonal points (L = 24, 16) extrapolate to gamma_L within 2%",
      abs(cL / GAML - 1) > 0.03 and abs(lin - 1) < 0.02, f"fit {cL/GAML:.3f} (res {rL:.0e}); small-s linear {lin:.3f}")
c16, r16 = symfit([p[0] for p in pts], [p[1] for p in pts], np.array([p[2][0] for p in pts]), 3)
mx16 = max(abs(v[0]) for v in M2.values())
ex16 = np.log(M2[(16, 2, 2)][0] / M2[(16, 1, 1)][0]) / np.log(np.sqrt(sv(16, 2) / sv(16, 1)))
loc = [np.log(diag[i + 1][3][0] / diag[i][3][0]) / np.log(diag[i + 1][0] / diag[i][0]) for i in range(2)]
check("P5 pre-set NOT MET at m0 = 1.6: R16 is not yet in a p^2 regime: |p|-exponent (L = 16, n = 1, 2) ~0.1, not in "
      "[1.6, 2.4], and the fitted intercept is not small; R16 peaks near s = 0.07 and its local s-exponent rises "
      "toward 1 at the smallest momenta (turnover toward zero)",
      not (1.6 <= ex16 <= 2.4) and abs(c16) > 0.01 * abs(GAML) and loc[0] > loc[1] > 0,
      f"exponent {ex16:.2f}; intercept {c16:+.1e} (0.01|gamma_L| = {0.01*abs(GAML):.1e}); local s-exponents "
      f"(s {diag[0][0]:.3f}-{diag[1][0]:.3f}) {loc[0]:.2f}, ({diag[1][0]:.3f}-{diag[2][0]:.3f}) {loc[1]:.2f}")
fs = abs(M2[(12, 3, 3)][0] - M2[(16, 4, 4)][0]) / mx16; fs8 = abs(M2[(8, 1, 1)][0] - M2[(16, 2, 2)][0]) / mx16
check("P6 pre-set MET: |R16_12 - R16_16| at (pi/2, pi/2) <= 1e-2 max|R16|; the L = 8 vs 16 difference at (pi/4, pi/4) "
      "is larger (finite size shrinking with L)", fs < 1e-2 and fs8 > fs, f"12/16 {fs:.1e}, 8/16 {fs8:.1e}")
ee = {tuple(int(t) for t in k.split(',')): v for k, v in DATA['M2eps'].items()}
sc = [np.log2(M2[k][0] / ee[k][0]) + 2 for k in ((8, 1, 1), (8, 2, 2), (12, 1, 1)) if k in ee]
check("P5b eps scaling at m0 = 1.6 (eps 0.3 vs 0.15): order eps^4 within 0.3 at s = 0.146, 0.5 (L = 8); NOT met at "
      "s = 0.067 (L = 12), where higher orders are large", abs(sc[0] - 4) < 0.3 and abs(sc[1] - 4) < 0.3 and abs(sc[2] - 4) > 0.3,
      "exponents " + ", ".join(f"{s:.2f}" for s in sc))

# ---------- P7: flux sector on 6^4 ----------
fx = DATA['M3']; idx = {int(k): v['index'] for k, v in fx.items()}; gaps = {int(k): v['gap'] for k, v in fx.items()}
fam = sum(m * Y * (-2 * idx[int(round(6 * abs(Y)))]) for m, Y in zip(MULT, YS)); dbl = 2 * (-0.5) * (-2 * idx[3])
check("P7 unit flux in the 12- and 34-planes on 6^4 (charge unit 1/6), full dense: indices of 6Y = 1..6 are "
      "-(6Y)^2 (all resolved, incl. e^c); the 16's flux integral = 0 from MEASURED integers; lone doublet -18",
      all(idx[q] == -q * q for q in idx) and abs(fam) < 1e-9 and abs(dbl + 18) < 1e-9,
      "indices " + ",".join(f"{idx[q]}" for q in sorted(idx)) + f"; min gap {min(gaps.values()):.2f}; 16 {fam:.0f}, doublet {dbl:.0f}")

# ---------- C. post-hoc control: the same test with Wilson mass m0 = 1.0 ----------
M2b = {tuple(int(t) for t in k.split(',')): v for k, v in DATA['M2m1'].items()}
db = sorted((sv(L, n), L, v) for (L, n, m), v in M2b.items() if n == m and 2 * n != L)
print("m0 = 1.0 diagonal: s, L, R16, R_L/gamma_L: " + "; ".join(f"{s:.3f} L{L} {v[0]:+.1e} {v[1]/GAML:.3f}" for s, L, v in db))
small = M2b[(16, 1, 1)]; ratio16 = abs(small[0]) / abs(M2[(16, 1, 1)][0])
sl = np.polyfit([d[0] for d in db if d[1] >= 12][:3], [d[2][1] / GAML for d in db if d[1] >= 12][:3], 1)
eb = {tuple(int(t) for t in k.split(',')): v for k, v in DATA['M2m1eps'].items()}
xb = np.log2(M2b[(8, 1, 1)][0] / eb[(8, 1, 1)][0]) + 2
exb = np.log(M2b[(16, 2, 2)][0] / M2b[(16, 1, 1)][0]) / np.log(np.sqrt(sv(16, 2) / sv(16, 1)))
check("C1 post-hoc control, m0 = 1.0 (not a pre-set criterion): the 16's coefficient at (pi/8, pi/8) is < 1e-3 "
      "|gamma_L| and < 1% of the m0 = 1.6 value; it falls at least like |p|^2 (exponent >= 1.6) and is order eps^4; "
      "the doublet still -> gamma_L (linear-in-s intercept within 2%)",
      abs(small[0]) < 1e-3 * abs(GAML) and ratio16 < 0.01 and exb >= 1.6 and abs(xb - 4) < 0.5 and abs(sl[1] - 1) < 0.02,
      f"R16 {small[0]:+.1e} ({ratio16:.1e} of m0 = 1.6); |p|-exponent {exb:.1f}; eps-exponent {xb:.2f}; "
      f"doublet intercept {sl[1]:.3f}")
Pm = {L: np.array(DATA['M1m1'][str(L)]) for L in (8, 12) if str(L) in DATA['M1m1']}
dm = {L: kernel_from_pi(L, Pm[L])[2].sum() / GAM - 1 for L in Pm}
check("C2 post-hoc control, m0 = 1.0: the per-charge zero-momentum value converges much faster (|dS| at L = 8 "
      "below 1/5 of the m0 = 1.6 value), consistent with the m0 = 1.6 slow scale being the near-doubler mass 2 - m0 = 0.4",
      abs(dm[8]) < 0.2 * abs(dS[8]), ", ".join(f"L{L} {d:+.2%}" for L, d in dm.items()) + f" vs m0 = 1.6 L8 {dS[8]:+.1%}")
print("Reading: Luscher's zero-momentum conditions hold exactly (flux integers; doublet keeps gamma_L). At m0 = 1.6")
print("the 16's density has a slow scale (reading: 2 - m0 = 0.4), not yet in its p^2 regime by L = 24; at m0 = 1.0 it")
print("is ~1e-6 at |p| = 0.39 and falls faster than p^2. Finite-lattice U(1) diagnostic; Luscher's theorem supplied.")
